search = [&](Counts a, std::vector<Block> sets) {
    if (a[first] >= 3) {
        a[first] -= 3;
        std::vector<Block> next = sets;
        next.push_back(Block{first});
        search(a, next);
        a[first] += 3;
    }
    if (first < 27 && first % 9 <= 6 && a[first + 1] > 0 && a[first + 2] > 0) {
        --a[first];
        --a[first + 1];
        --a[first + 2];
        sets.push_back(Block{first, true});
        search(a, sets);
    }
